package au.monster.tracker;
import java.util.*;
public final class FinanceBackup {
    public static Map<String,Object> taxMap(Finance.Tax tax){Map<String,Object> m=new LinkedHashMap<>();m.put("registered",tax.registered());m.put("actualGst",tax.actualGst());m.put("inputGst",tax.inputGst());m.put("outputGst",tax.outputGst());return m;}
    public static boolean bool(Map<String,Object> m,String key){if(!(m.get(key) instanceof Boolean))Purchases.bad("Invalid GST flag.");return (Boolean)m.get(key);}
    public static Finance.Tax tax(Object value){var m=Purchases.map(value);if(!m.keySet().equals(Ledger.set("registered","actualGst","inputGst","outputGst")))Purchases.bad("Invalid tax snapshot fields.");return new Finance.Tax(bool(m,"registered"),Purchases.num(m,"actualGst"),Purchases.num(m,"inputGst"),Purchases.num(m,"outputGst"));}
    public static void settings(Map<String,Object> settings,Set<String> productIds){for(var entry:settings.entrySet()){var m=Purchases.map(entry.getValue());if(entry.getKey().equals("gst")){if(!m.keySet().equals(Ledger.set("registered","expenseCredits")))Purchases.bad("Invalid GST settings.");bool(m,"registered");bool(m,"expenseCredits");}else {if(!entry.getKey().startsWith("product:")||!productIds.contains(entry.getKey().substring(8))||!m.keySet().equals(Ledger.set("treatment"))||!Ledger.set("taxable","gst_free","input_taxed").contains(Purchases.str(m,"treatment")))Purchases.bad("Invalid product tax treatment.");}}if(!settings.containsKey("gst"))Purchases.bad("GST settings are missing.");}
    public static void validate(Map<String,Object> data,List<Ledger.Event> events,List<Purchases.Document> documents,Set<String> productIds){if(!data.keySet().equals(Ledger.set("settings","taxes")))Purchases.bad("Invalid finance backup fields.");settings(Purchases.map(data.get("settings")),productIds);Map<String,Ledger.Event> ledger=new HashMap<>();for(var e:events)ledger.put(e.id(),e);Map<String,Long> expense=new HashMap<>();for(var d:documents){long gross=0;if(d.kind().equals("expense"))gross=d.amount();else for(var l:d.lines())if(!l.stock())gross+=l.cost();expense.put(d.id(),gross);}Set<String> ids=new HashSet<>();for(Object value:Purchases.list(data.get("taxes"))){var m=Purchases.map(value);String id=Purchases.str(m,"id"),kind=Purchases.str(m,"kind");if(!ids.add(id))Purchases.bad("Duplicate historical tax ID.");var tax=tax(m.get("tax"));if(kind.equals("ledger")){var e=ledger.get(id);if(e==null||tax.actualGst()>e.cost()||tax.outputGst()>e.revenue()||(!e.type().equals("restock")&&tax.inputGst()!=0))Purchases.bad("Invalid ledger GST association.");}else if(kind.equals("document")){if(!expense.containsKey(id)||tax.actualGst()>expense.get(id)||tax.outputGst()!=0)Purchases.bad("Invalid expense GST association.");}else Purchases.bad("Unknown tax source type.");}}
    private FinanceBackup(){}
}
